// 示意图：3副本场景下的 LEO 与 HW
//
// Partition 0, RF=3, ISR=[Leader, F1, F2]
//
//         offset: 0  1  2  3  4  5
// Leader:         [A][B][C][D][E]      LEO=5
// Follower1:      [A][B][C][D]         LEO=4
// Follower2:      [A][B][C]            LEO=3
//
// HW = min(5, 4, 3) = 3
// 消费者最多消费到 offset=2（HW-1），消息 D、E 对消费者不可见
//
// 当 F2 追上后（LEO=5），HW 推进到 5，D、E 才对消费者可见

# Broker 端（server.properties）
default.replication.factor=3
min.insync.replicas=2
unclean.leader.election.enable=false

# 生产者端（Java ProducerConfig）
props.put("acks", "all");
props.put("retries", Integer.MAX_VALUE);
props.put("enable.idempotence", "true");       // 开启幂等，重试安全
props.put("max.in.flight.requests.per.connection", "5"); // 幂等模式最大5

# 消费者端
props.put("enable.auto.commit", "false");      // 关闭自动提交
// 业务处理成功后手动提交
consumer.commitSync();
